package repository;

import constants.Constants;
import constants.Message;
import dto.NoteRequestDTO;
import java.util.ArrayList;
import java.util.List;
import model.Note;

/**
 * REPOSITORY: holds the notes and performs simple CRUD on them. No check of what was typed
 * (Main did it), no print.
 *
 * @author CuongThai Academy
 */
public class NoteRepository {

    // The "database" of notes, in the order they were added.
    private List<Note> noteList;

    // Creates an empty repository.
    public NoteRepository() {
        noteList = new ArrayList<>(List.of());
    }

    // Stores the note Main has already checked, with ID = last ID + 1, and returns that ID.
    public int addNote(NoteRequestDTO requestDTO) {
        Note note = new Note(generateNextId(), requestDTO.getContent());

        // keep it after the others
        noteList.add(note);
        return note.getId();
    }

    // Removes the note with the request's ID; an unknown ID is refused.
    public void deleteNote(NoteRequestDTO requestDTO) throws Exception {
        // look at every note until the ID matches
        for (int i = 0; i < noteList.size(); i++) {
            // found it: remove by position and stop
            if (noteList.get(i).getId() == requestDTO.getId()) {
                noteList.remove(i);
                return;
            }
        }

        // no note has this ID
        throw new Exception(String.format(Message.NOTE_NOT_EXIST, requestDTO.getId()));
    }

    // Every note as one row of the table, in the order they were added.
    public List<String> getDataNotes() {
        List<String> rowList = new ArrayList<>();

        // one row per stored note, text built by the model's toString()
        for (Note note : noteList) {
            rowList.add(note.toString());
        }

        return rowList;
    }

    // The ID rule: the first note gets ID 1, every next one the last ID + 1.
    private int generateNextId() {
        // empty list: the first note gets ID 1
        if (noteList.isEmpty()) {
            return Constants.FIRST_ID;
        }

        return noteList.get(noteList.size() - 1).getId() + Constants.ID_STEP;
    }
}

package utils;

import constants.Message;

/**
 * Shared checks for what the user typed. A utility: no object, no keyboard, no print - it
 * turns one typed line into a clean value, or throws the message of the broken rule.
 *
 * @author CuongThai Academy
 */
public final class Validation {

    // Private constructor: every method is called through the class name.
    private Validation() {
    }

    // Returns the text without surrounding spaces.
    public static String getText(String input) {
        // a missing line is treated like an empty one
        if (input == null) {
            return "";
        }

        return input.trim();
    }

    // Converts a menu choice and checks it lies in [min, max].
    public static int getChoice(String input, int min, int max) throws Exception {
        int choice = 0;

        // parse first, so a letter gives the "number" message
        try {
            choice = Integer.parseInt(getText(input));
        } catch (NumberFormatException e) {
            // letters or an empty line: not a number at all
            throw new Exception(Message.INVALID_NUMBER);
        }

        // then check the range, so 9 gives the "range" message
        if ((choice < min) || (choice > max)) {
            throw new Exception(String.format(Message.INVALID_RANGE, min, max));
        }

        return choice;
    }

    // Returns the text when it is not blank.
    public static String getRequired(String input, String error) throws Exception {
        String text = getText(input);

        // blank text is refused
        if (text.isEmpty()) {
            throw new Exception(error);
        }

        return text;
    }

    // Converts the ID typed on the delete screen.
    public static int getId(String input) throws Exception {
        String text = getRequired(input, Message.ID_EMPTY);

        // Integer (wrapper class) decides whether the text is a number
        try {
            return Integer.parseInt(text);
        } catch (NumberFormatException e) {
            // letters or a decimal
            throw new Exception(Message.ID_NOT_NUMBER);
        }
    }
}

package view;

import constants.Constants;
import constants.Message;
import dto.NoteResponseDTO;

/**
 * VIEW: the only place (with main) allowed to print results. It receives the data through
 * its attribute (the ResponseDTO), never through the parameters of display().
 *
 * @author CuongThai Academy
 */
public class NoteView {

    // The answer to print, handed over by the controller.
    private NoteResponseDTO responseDTO;

    // Receives the answer the next display() call will print.
    public void setResponseDTO(NoteResponseDTO responseDTO) {
        this.responseDTO = responseDTO;
    }

    // Prints what the controller set: the line of an add or a delete, or the note table.
    public void display() {
        // options 1 and 2: only the line of the result was set
        if (responseDTO.getRowList() == null) {
            System.out.println(responseDTO.getMessage());
            return;
        }

        // option 3: the title of the table comes first, even when there is no note
        System.out.println(Message.TITLE_NOTE);

        // nothing added yet (or everything deleted)
        if (responseDTO.getRowList().isEmpty()) {
            System.out.println(Message.NO_NOTE);
            return;
        }

        // the header, with the same column widths as the rows
        System.out.println(String.format(Constants.HEADER_FORMAT, Message.LABEL_ID,
                Message.LABEL_CONTENT));

        // one line per note
        for (String row : responseDTO.getRowList()) {
            System.out.println(row);
        }
    }
}

